script:
(function () {
  'use strict';
  // Amortizing loan schedule for any fixed-rate loan, any payment frequency.
  //   Periodic rate i = annual rate / payments per year; n = round(term in months * per year / 12).
  //   Payment: P = L * i / (1 - (1 + i)^-n)  (P = L / n at 0%).
  //   Loan from payment: L = P * (1 - (1 + i)^-n) / i  (L = P * n at 0%).
  //   Each period: interest = balance * i, principal = P - interest; the last payment clears the balance.
  // Verified in Node (scratchpad tests/m5): $200,000 at 6% for 15 yrs monthly = $1,687.71
  //   (closed form; matches a published calculator's default), total interest $103,788.46;
  //   $1,687.71 at 6% for 180 months solves back to $199,999.57 (the payment is rounded);
  //   $10,000 at 0% for 2 yrs = $416.67/mo; biweekly 30-yr $300,000 at 6.5% uses 780 periods at 0.25%;
  //   final balance is exactly 0; crossover and half-repaid milestones match an independent loop;
  //   no NaN/Infinity on blank, zero or negative input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var PAY_LABEL = { '12': 'Monthly payment', '24': 'Semi-monthly payment', '26': 'Biweekly payment',
                    '52': 'Weekly payment', '4': 'Quarterly payment', '1': 'Annual payment' };
  var last = null;

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function paymentFor(loan, i, n) {
    if (n <= 0 || loan <= 0) return 0;
    if (i === 0) return loan / n;
    return loan * i / (1 - Math.pow(1 + i, -n));
  }

  function loanFor(pay, i, n) {
    if (n <= 0 || pay <= 0) return 0;
    if (i === 0) return pay * n;
    return pay * (1 - Math.pow(1 + i, -n)) / i;
  }

  function schedule(loan, i, n, pay) {
    var bal = loan, cum = 0, rows = [];
    for (var k = 1; k <= n && bal > 0.005; k++) {
      var interest = bal * i;
      var principal = k === n ? bal : Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      cum += interest;
      rows.push({ n: k, principal: principal, interest: interest, cum: cum, balance: bal });
    }
    return rows;
  }

  function pct(x) { return (x * 100).toFixed(1) + '%'; }

  function clearResults() {
    ['amMain', 'amTotalPaid', 'amTotalInterest', 'amCount', 'amShare', 'amCrossover', 'amHalfway',
     'amFiveYear'].forEach(function (id) { setText(id, '–'); });
    el('amSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var head = el('amScheduleHead'), body = el('amSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var rows = last.rows, f = last.freq, loan = last.loan, html = [];
    if (el('amView').value === 'period') {
      head.innerHTML = '<tr><th scope="col">Payment</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Total interest</th><th scope="col">Balance</th></tr>';
      rows.forEach(function (r) {
        html.push('<tr><td>' + r.n + '</td><td>' + money.format(r.principal) + '</td><td>' + money.format(r.interest) +
          '</td><td>' + money.format(r.cum) + '</td><td>' + money.format(r.balance) + '</td></tr>');
      });
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Total interest</th><th scope="col">Balance</th><th scope="col">Repaid</th></tr>';
      var p = 0, intr = 0;
      rows.forEach(function (r, idx) {
        p += r.principal; intr += r.interest;
        if (r.n % f === 0 || idx === rows.length - 1) {
          html.push('<tr><td>' + Math.ceil(r.n / f) + '</td><td>' + money.format(p) + '</td><td>' + money.format(intr) +
            '</td><td>' + money.format(r.cum) + '</td><td>' + money.format(r.balance) + '</td><td>' +
            pct(loan > 0 ? 1 - r.balance / loan : 1) + '</td></tr>');
          p = 0; intr = 0;
        }
      });
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var solve = el('amSolve').value, freq = parseInt(el('amFreq').value, 10);
    el('amAmountWrap').hidden = solve !== 'payment';
    el('amPaymentWrap').hidden = solve === 'payment';
    var amount = read('amAmount'), pay = read('amPayment'), rate = read('amRate'),
        years = read('amYears', true), months = read('amMonths', true);
    var totalMonths = years * 12 + months;
    var n = Math.round(totalMonths * freq / 12);
    var error = el('amError'), msg = '';
    if (solve === 'payment' && (isNaN(amount) || amount <= 0)) msg = 'Enter a loan amount greater than $0.';
    else if (solve !== 'payment' && (isNaN(pay) || pay <= 0)) msg = 'Enter a payment greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (isNaN(years) || isNaN(months) || years < 0 || months < 0 || months > 11 || years % 1 !== 0 || months % 1 !== 0)
      msg = 'Enter the term in whole years and 0 to 11 extra months.';
    else if (totalMonths < 1 || totalMonths > 600) msg = 'Enter a loan term from 1 month to 50 years.';
    else if (n < 1) msg = 'The term is shorter than one payment period. Lengthen the term or pay more often.';
    error.hidden = !msg;
    error.textContent = msg;
    setText('amMainLabel', solve === 'payment' ? (PAY_LABEL[String(freq)] || 'Payment') : 'Loan amount');
    if (msg) { clearResults(); return; }

    var i = rate / 100 / freq;
    var loan = solve === 'payment' ? amount : loanFor(pay, i, n);
    var p = solve === 'payment' ? paymentFor(amount, i, n) : pay;
    var rows = schedule(loan, i, n, p);
    var totalInterest = rows.length ? rows[rows.length - 1].cum : 0;

    setText('amMain', money.format(solve === 'payment' ? p : loan));
    setText('amTotalPaid', money.format(loan + totalInterest));
    setText('amTotalInterest', money.format(totalInterest));
    setText('amCount', String(rows.length));
    setText('amShare', pct(loan + totalInterest > 0 ? totalInterest / (loan + totalInterest) : 0));

    var cross = null, half = null;
    rows.forEach(function (r) {
      if (cross === null && r.principal >= r.interest) cross = r.n;
      if (half === null && r.balance <= loan / 2) half = r.n;
    });
    function at(k) { return k === null ? '–' : 'Payment ' + k + ' (year ' + Math.ceil(k / freq) + ')'; }
    setText('amCrossover', cross === 1 ? 'From the first payment' : at(cross));
    setText('amHalfway', at(half));
    var fiveIdx = Math.min(5 * freq, rows.length) - 1;
    var fiveBal = fiveIdx >= 0 ? rows[fiveIdx].balance : loan;
    setText('amFiveYear', rows.length <= 5 * freq ? 'Paid off within 5 years' : pct(1 - fiveBal / loan) + ' of the loan');

    last = { rows: rows, freq: freq, loan: loan };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('amForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('amView').addEventListener('change', renderSchedule);
    update();
  });
})();
